WITH with_gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY device ORDER BY started_at ASC, id ASC) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY device ORDER BY started_at ASC, id ASC) + INTERVAL '60' DAY THEN 1 ELSE 0 END AS new_group_flag FROM sessions) SELECT *, SUM(new_group_flag) OVER (PARTITION BY device ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps
